import { WORKSPACE_DEFAULTS } from "./workspace-defaults.mjs";

const hasOverride = (overrides, key) =>
  overrides !== null &&
  typeof overrides === "object" &&
  Object.hasOwn(overrides, key) &&
  overrides[key] !== undefined;

export function resolveSettings(overrides = {}) {
  const resolved = {};
  for (const key of Object.keys(WORKSPACE_DEFAULTS)) {
    resolved[key] = hasOverride(overrides, key) ? overrides[key] : WORKSPACE_DEFAULTS[key];
  }
  for (const key of Object.keys(overrides ?? {})) {
    if (!Object.hasOwn(resolved, key)) resolved[key] = overrides[key];
  }
  return resolved;
}

export function settingValue(key, overrides = {}) {
  return hasOverride(overrides, key) ? overrides[key] : WORKSPACE_DEFAULTS[key];
}

